import Foundation
import XCTest

/// Loads fixtures committed under `Tests/VaultKitTests/Fixtures`.
///
/// The fixtures are generated by an *independent* implementation
/// (`tools/derive/`, Python + pycryptodome) or copied verbatim from the
/// published standards (BIP39 wordlist and Trezor vectors), so tests that use
/// them are differential rather than self-referential.
enum FixtureLoader {
    static func url(_ name: String, extension ext: String, subdirectory: String = "Fixtures") throws -> URL {
        guard let url = Bundle.module.url(
            forResource: name,
            withExtension: ext,
            subdirectory: subdirectory
        ) else {
            throw FixtureError.missing("\(name).\(ext)")
        }
        return url
    }

    static func data(_ name: String, extension ext: String, subdirectory: String = "Fixtures") throws -> Data {
        try Data(contentsOf: url(name, extension: ext, subdirectory: subdirectory))
    }

    static func text(_ name: String, extension ext: String) throws -> String {
        guard let string = String(data: try data(name, extension: ext), encoding: .utf8) else {
            throw FixtureError.notUTF8("\(name).\(ext)")
        }
        return string
    }

    static func json(_ name: String, extension ext: String, subdirectory: String = "Fixtures") throws -> Any {
        try JSONSerialization.jsonObject(with: try data(name, extension: ext, subdirectory: subdirectory))
    }

    enum FixtureError: Error, CustomStringConvertible {
        case missing(String)
        case notUTF8(String)

        var description: String {
            switch self {
            case .missing(let name): return "Missing fixture: \(name)"
            case .notUTF8(let name): return "Fixture is not UTF-8: \(name)"
            }
        }
    }
}

/// The reference implementation's `eth-sign-request`, as a wallet writes it.
///
/// Loaded here rather than inside one test class because two things need the same bytes: that
/// the app can read them, and that it can sign them.
struct EthURReferenceFixture: Decodable {
    struct Request: Decodable {
        let ur: String
        let requestID: String

        enum CodingKeys: String, CodingKey {
            case ur, inputs
        }
        enum InputKeys: String, CodingKey {
            case requestId
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            ur = try container.decode(String.self, forKey: .ur)
            let inputs = try container.nestedContainer(keyedBy: InputKeys.self, forKey: .inputs)
            requestID = try inputs.decode(String.self, forKey: .requestId)
        }
    }

    struct Signature: Decodable {
        let ur: String
    }

    let request: Request
    let signature: Signature

    static func load() throws -> EthURReferenceFixture {
        let data = try FixtureLoader.data("eth_ur_reference", extension: "json")
        return try JSONDecoder().decode(EthURReferenceFixture.self, from: data)
    }
}
